using System.Configuration; using System.Data; using System.Data.SqlClient; namespace PlacementDashboard { public static class DBConnection { public static SqlConnection GetConnection() { return new SqlConnection(ConfigurationManager.ConnectionStrings["PlacementDb"].ConnectionString); } public static DataTable GetStudents() { using (var c=GetConnection()) using (var a=new SqlDataAdapter("SELECT StudentId,StudentName,Department,Company,Package,PlacementStatus FROM Students ORDER BY StudentName",c)) { var t=new DataTable(); a.Fill(t); return t; } } public static int Execute(string sql, params SqlParameter[] p) { using (var c=GetConnection()) using (var q=new SqlCommand(sql,c)) { q.Parameters.AddRange(p); c.Open(); return q.ExecuteNonQuery(); } } public static int Count(string status) { using(var c=GetConnection()) using(var q=new SqlCommand("SELECT COUNT(*) FROM Students WHERE PlacementStatus=@s",c)) { q.Parameters.AddWithValue("@s",status); c.Open(); return (int)q.ExecuteScalar(); } } } }
